head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
 ASIS에서 문법에 어긋난 문장이 발견되었습니다. 이는 WCRAFT에서 X 로 변환합니다.  
 X 로 변환된 곳을 찾아 ASIS소스를 참고하여 문법에 맞도록 변환해주세요. 

----------------------------------------------------
[0] 기존 문법 오류
----------------------------------------------------
	> X 오류 확인 - 기존 소스 확인 필요

*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
scwin.gAcptNo;
scwin.gIsurCd;
scwin.gDate;
scwin.gDepCd;
scwin.gEmpNo;
scwin.gLdMktTp;
scwin.gPageSize = 10; //페이지 size
scwin.gTotalCnt = 0; //전체 row
scwin.gPageNoCnt = 10; //page 번호 개수
scwin.vCurrPageNo = 0; //현재 선택된 페이지번호

scwin.vScrenID = 'ULDSTF35800.xml';
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_SetCode = function() {
    scwin.gDepCd = js_dep_cd;
    scwin.gEmpNo = js_emp_no;
    scwin.gLdMktTp = js_market;

    //  기간 from~ to  셋팅	
    vCurDate = $c.ut.cGetToday("yyyymmdd");
    edt_FromDate.setValue($c.ut.cGetMinusYear(vCurDate, 1)); //  1년전  날짜
    edt_ToDate.setValue($c.ut.cGetToday("yyyymmdd")); // 현재날짜

    // 불성실유형  셋팅
    dts_NfaithTp.DataID = "/CodeAction.do?method=listCodeValueName&inputMessageId=CODEVALUE_INOUT&outputMessageId=CODE_OUT" + "&FOR=C&CD_ENG_NM=NFAITH_TP_CD";
    dts_NfaithTp.Reset();

    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************

};X < !불성실지정예고--;
클릭-- > function() {
    // 일자 체크
    if ($c.stf.getObjectValue(edt_FromDate).length < 8) {
        $c.win.alert("일자 올바르게 입력하십시오.");
        edt_FromDate.focus();
        return;
    }

    // 일자 체크
    if ($c.stf.getObjectValue(edt_ToDate).length < 8) {
        $c.win.alert("일자 올바르게 입력하십시오.");
        edt_ToDate.focus();
        return;
    }
    if ($c.stf.compareFromToDate2(edt_FromDate, edt_ToDate) == false) {
        return;
    }
    fn_Search();
};
scwin.getChkValue = function(obj) {
    //return (obj.checked) ? "Y" : "N";
    if (obj.checked == true) {
        return obj.getValue();
    } else {
        return "0";
    }

    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************

};X < !불성실지정--;
목록검색(유가증권);
사용자;
클릭-- > function() {
    scwin.vCurrPageNo = 0;
    var bndListStat = scwin.getChkValue(chb_ListStatCd);
    if (bndListStat == "0") {
        bndListStat = "2"; //채권공시 해제법인

    }
    var url_list = "/UnfaithfulDesign.do?method=listUnfaithfulSecuMktBond&inputMessageId=NFAITHSECUMKTCONDBOND_IN" + "&outputMessageId=NFAITHSECUMKTLISTBOND_OUT";
    var url_cond = "&ISUR_CD=" + $c.stf.getObjectValue(txb_isur_cd) + "&FROM_DATE=" + $c.stf.getObjectValue(edt_FromDate) + "&TO_DATE=" + $c.stf.getObjectValue(edt_ToDate) + "&BND_LIST_STAT=" + bndListStat + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;

    // 그리드의 데이타 조회
    dts_nfaith_list.DataID = encodeURI(url_list + url_cond);
    dts_nfaith_list.reset();
    $c.cm.ShowWin(grd_nfaith_list);

    /*
    txb_companyCnt.value = "총회사수 : " ;
    var url_list2 = "/UnfaithfulDesign.do?method=listUnfaithfulKosdaqCnt&inputMessageId=NFAITHKOSDAQCOND_IN"
    		+ "&outputMessageId=NFAITHKOSDAQLISTCNT_OUT" ;			
    var url_cond2 =  "&ISUR_CD="+ getObjectValue(txb_isur_cd)
    		+ "&FROM_DATE=" + getObjectValue(edt_FromDate)
    		+ "&TO_DATE=" + getObjectValue(edt_ToDate)
    		+ "&BND_LIST_STAT=" + bndListStat;	

    // 그리드의 데이타 조회
    bnc_Company_Cnt.DataID = encodeURI(url_list2 + url_cond2);
    bnc_Company_Cnt.reset();
    */

};



// 그리드에서 클릭 row의 변수셋팅
scwin.fn_setContnId = function(obj) {
    scwin.gAcptNo = dts_nfaith_list.getCellData(eval(obj), "ACPT_NO");
    scwin.gIsurCd = dts_nfaith_list.getCellData(eval(obj), "ISUR_CD");
};
scwin.grd_nfaith_list_OnDblClick = function(row, colid) {
    scwin.fn_setContnId(row);
    if (colid == "COM_ABBRV") {
        $c.stf.fn_PopupCorpInfo();
    } else if (colid == "CONTN") {
        //2017-11-29 KBoY 비공개 첨부서류 볼 수 없음.
        $c.stf.fn_OpenDisclViewer(scwin.gAcptNo, "R", scwin.vScrenID);
    } else if (colid == "BND_ISU_NM") {
        //2017-11-29 KBoY 비공개 첨부서류 볼 수 없음.
        $c.stf.fn_OpenDisclViewer(scwin.gAcptNo, "R", scwin.vScrenID);
    } else if (colid == "RSN_OCCR_DD") {
        //2017-11-29 KBoY 비공개 첨부서류 볼 수 없음.
        $c.stf.fn_OpenDisclViewer(scwin.gAcptNo, "R", scwin.vScrenID);
    }
};
scwin.btn_Search_onclick = function() {
    fn_CheckCond();
};
scwin.btn_Excel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
    $c.data.downloadGridViewExcel(grd_nfaith_list, "불성실공시법인지정 목록", "", "8");
};
scwin.dts_NfaithTp_OnLoadError = function() {
    $c.stf.alert_error(dts_NfaithTp);
};
scwin.dts_nfaith_list_OnLoadError = function() {
    $c.stf.alert_error(dts_nfaith_list);
    $c.cm.CloseWin('', grd_nfaith_list);
};
scwin.img_FromCal_onclick = function() {
    popUpCalendar2(edt_FromDate);
};
scwin.img_ToCal_onclick = function() {
    popUpCalendar2(edt_ToDate);
};
scwin.cmb_PeriodTp_OnSelChange = function() {
    var vTp = $c.cp.valueOfIndex(cmb_PeriodTp, "VALUE", cmb_PeriodTp.getSelectedIndex());
    $c.stf.fn_setFromToDate(vTp, edt_FromDate, edt_ToDate);
};
scwin.dts_nfaith_list_OnLoadCompleted = function(rowcount) {
    if (dts_nfaith_list.errorMsg) {
        $c.win.alert(dts_nfaith_list.errorMsg);
    } else {
        $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    }
    $c.cm.CloseWin(rowcount, grd_nfaith_list);
};
scwin.txb_isur_cd_onblur = function() {
    if (stFocusGrid == false) {
        Grd_com_isur.style.display = "none";
    }
    if (txb_isur_cd.getValue() == "") {
        txb_com_abbrv.setValue("");
    }
};
scwin.txb_isur_cd_onfocus = function() {
    Grd_com_isur.style.display = "none";
};
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    if (skw != "" && foColum == "1") {
        f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
        f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
        if (f1.indexOf(skw) != -1 || f2.indexOf(skw) != -1) return true;

        else return false;
    } else return true;
};
scwin.txb_isur_cd_onkeyup = function() {
    if (txb_isur_cd.getValue() == "") {
        Grd_com_isur.style.display = "none";
    } else {
        if (window.event.keyCode == 40) {
            //아래화살표눌렀을때 그리드로 포커스
            Grd_com_isur.focus();
        } else {
            $c.cm.fn_com_isur_nm(window.event.keyCode);
        }
    }
};
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    if (kcode == '13') {
        $c.cm.fn_com_Confirm_set();
    }
};
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    $c.cm.fn_com_Confirm_set();
};
scwin.Grd_com_isur_OnClick = function(row, colid) {
    Grd_com_isur.style.display = "";
};
scwin.Grd_com_isur_OnSetFocus = function() {
    stFocusGrid = true;
};
scwin.Grd_com_isur_OnKillFocus = function() {
    stFocusGrid = false;
    Grd_com_isur.style.display = "none";
};
scwin.img_com_srch_onclick = function() {
    $c.cm.IsurcdSearchBond(txb_isur_cd, txb_com_abbrv);
};
scwin.gform_onload = function() {
    // 패널라운드 처리
    $c.cm.PanelToGroupBox(panel_1);
    $c.stf.Combo_CBDataSetPeriod(cmb_PeriodTp);
    scwin.fn_SetCode();
    $c.cm.fn_com_isur(txb_isur_cd, txb_com_abbrv);
    fn_CheckCond();
};
